def delete(data, path):
    keys = path.split('.')
    for key in keys[:-1]:
        if isinstance(data, dict) and key in data:
            data = data[key]
        else:
            raise KeyError("Invalid path")
    if isinstance(data, dict) and keys[-1] in data:
        value = data[keys[-1]]
        del data[keys[-1]]
        return value
    else:
        raise KeyError("Invalid path")

if __name__ == "__main__":
    # Test cases for delete function
    data = {
        "a": {
            "b": {
                "c": 1
            }
        }
    }
    try:
        assert delete(data, "a.b.c") == 1
        assert "c" not in data["a"]["b"]
    except KeyError as e:
        print(f"KeyError: {e}")

    try:
        delete(data, "a.b.d")
    except KeyError as e:
        assert str(e) == "Invalid path"
    else:
        print("Test failed: KeyError not raised for invalid path")

